/// <summary>
/// MPJ_43843_ARDashboard
/// Adding new methods for AR dashboard to show number of journal lines posted/not posted
/// </summary>
[ExtensionOf(tableStr(DMFExecution))]
final class METDMFExecution_Extension
{
}

Method.Source:
/// <summary>
/// Display method for number of journal lines not posted
/// </summary>
/// <returns>number of journal lines not posted</returns>
public display DMFTargetRecordCount METGetJounalNotPostedRecordCount()
{
    return this.METGetJounalLinesRecordCount(NoYes::No);
}

/// <summary>
/// Display method for number of journal lines not posted
/// </summary>
/// <returns>number of journal lines not posted</returns>
public display DMFTargetRecordCount METGetJounalPostedRecordCount()
{        
    return this.METGetJounalLinesRecordCount(NoYes::Yes);
}

/// <summary>
/// Method to calculated number of journal lines posted or not posted
/// Originally copied from DMFExecution\getNewTargetRecordCount
/// </summary>
/// <param name = "_posted">To filter lines posted or not posted</param>
/// <returns>number of journal lines posted or not posted</returns>
public DMFTargetRecordCount METGetJounalLinesRecordCount(NoYes  _posted)
{
    DMFDefinitionGroupExecution definitionGroupExecution;
    DMFEntity                   dmfEntity;
    LedgerJournalTrans          ledgerJournalTrans;
    LedgerJournalTable          ledgerJournalTable;
    LedgerJournalEntityStaging  ledgerJournalEntityStaging;
        
    if (this.hasReRun(this))
    {
        select firstonly1 crosscompany count(RecId) from ledgerJournalTrans
            exists join ledgerJournalTable
                where ledgerJournalTable.JournalNum == ledgerJournalTrans.JournalNum
                    && ledgerJournalTable.Posted == _posted
            exists join ledgerJournalEntityStaging
                group by JournalBatchNumber
                where ledgerJournalEntityStaging.ExecutionId == this.ExecutionId
                    && ledgerJournalEntityStaging.JournalBatchNumber == ledgerJournalTable.JournalNum
            exists join definitionGroupExecution
                where definitionGroupExecution.ExecutionId == this.ExecutionId
                    && definitionGroupExecution.ReRun == (NoYes::Yes)
                    && definitionGroupExecution.Company == ledgerJournalTrans.DataAreaId
            exists join dmfEntity
                where dmfEntity.EntityName == definitionGroupExecution.Entity
                    && dmfEntity.ParentEntityName == '';
    }
    else
    {
        select firstonly1 crosscompany count(RecId) from ledgerJournalTrans
            exists join ledgerJournalTable
                where ledgerJournalTable.JournalNum == ledgerJournalTrans.JournalNum
                    && ledgerJournalTable.Posted == _posted
            exists join ledgerJournalEntityStaging
                group by JournalBatchNumber
                where ledgerJournalEntityStaging.ExecutionId == this.ExecutionId
                    && ledgerJournalEntityStaging.JournalBatchNumber == ledgerJournalTable.JournalNum
            exists join definitionGroupExecution
                where definitionGroupExecution.ExecutionId == this.ExecutionId
                   && definitionGroupExecution.Company == ledgerJournalTrans.DataAreaId
            exists join dmfEntity
                where dmfEntity.EntityName == definitionGroupExecution.Entity
                    && dmfEntity.ParentEntityName == '';
    }
   
    return ledgerJournalTrans.RecId;
}
